}

'use client';

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Loading states.
 *
 * Each skeleton is shaped like the thing it replaces - the ladder skeleton has
 * a spread row, the chart skeleton has an axis and a volume pane - so the
 * layout does not jump when real data lands and the eye already knows where to
 * look. A generic grey box would be cheaper and would cost a reflow every time.
 *
 * The pulse is opacity only, and stops under `prefers-reduced-motion`.
 */
export function Skeleton({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="skeleton"
      className={cn('bg-muted-foreground/15 animate-shimmer rounded-sm', className)}
      {...props}
    />
  );
}

/** Deterministic widths: random ones would re-roll on every render. */
const LADDER_WIDTHS = [62, 48, 74, 55, 68, 44, 80, 51, 66, 58, 72, 46];

export function OrderBookSkeleton({ depth = 8, className }: { depth?: number; className?: string }) {
  const row = (key: string, i: number, side: 'bid' | 'ask') => (
    <div key={key} className="flex items-center gap-2 px-2.5 py-[5px]">
      <Skeleton
        className={cn('h-2.5 flex-1', side === 'bid' ? 'bg-up/15' : 'bg-down/15')}
        style={{ maxWidth: `${LADDER_WIDTHS[i % LADDER_WIDTHS.length]}%` }}
      />
      <Skeleton className="h-2.5 w-10" />
      <Skeleton className="h-2.5 w-8" />
    </div>
  );

  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-10" />
        <Skeleton className="ml-auto h-2 w-8" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`a${i}`, i, 'ask'))}
      <div className="bg-muted my-0.5 flex items-center justify-between border-y px-2.5 py-2">
        <Skeleton className="h-2.5 w-16" />
        <Skeleton className="h-2.5 w-20" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`b${i}`, i + 3, 'bid'))}
    </div>
  );
}

export function TradeTapeSkeleton({ rows = 10, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-8" />
        <Skeleton className="ml-auto h-2 w-10" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="grid grid-cols-3 gap-2 px-2.5 py-[5px]">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-2.5 w-12 justify-self-end" />
          <Skeleton className="h-2.5 w-8 justify-self-end" />
        </div>
      ))}
    </div>
  );
}

/** Candle bars at varied heights around a baseline, plus axis and volume. */
const CANDLE_HEIGHTS = [38, 52, 44, 61, 49, 70, 57, 42, 66, 51, 74, 46, 59, 68, 40, 55, 63, 47];

export function CandleChartSkeleton({
  height = 320,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <div
      className={cn('flex w-full flex-col gap-2 p-2', className)}
      style={{ height }}
      aria-hidden="true"
    >
      <div className="flex min-h-0 flex-1 items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1"
            style={{ height: `${h}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex h-[16%] items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1 opacity-60"
            style={{ height: `${h * 0.7}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex justify-between pr-14">
        {Array.from({ length: 6 }, (_, i) => (
          <Skeleton key={i} className="h-2 w-8" />
        ))}
      </div>
    </div>
  );
}

export function TableSkeleton({
  rows = 4,
  columns = 6,
  className,
}: {
  rows?: number;
  columns?: number;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-4 border-b px-2.5 py-2">
        {Array.from({ length: columns }, (_, i) => (
          <Skeleton key={i} className={cn('h-2', i === 0 ? 'w-14' : 'flex-1')} />
        ))}
      </div>
      {Array.from({ length: rows }, (_, r) => (
        <div key={r} className="flex gap-4 border-b px-2.5 py-2.5">
          {Array.from({ length: columns }, (_, i) => (
            <Skeleton key={i} className={cn('h-2.5', i === 0 ? 'w-14' : 'flex-1')} />
          ))}
        </div>
      ))}
    </div>
  );
}

export function WatchlistSkeleton({ rows = 6, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-2.5 border-b px-2.5 py-2">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-4 w-14" />
          <Skeleton className="ml-auto h-2.5 w-12" />
          <Skeleton className="h-2.5 w-10" />
        </div>
      ))}
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { formatMoney, formatPrice, formatQuantity, formatTime } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Fill, Instrument } from '../../types';
import { Badge } from '../ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from '../ui/table';
import { cn, toArray } from '../../utils';
import { EmptyState } from './empty-state';
import { EmptyTapeArt } from './illustrations';
import { TableSkeleton } from './skeletons';

export interface FillsTableProps {
  fills: Fill[];
  instrument?: Partial<Instrument>;
  /** Fee column and the fee total. Off for venues that bundle fees into price. */
  showFees?: boolean;
  /** Maker/taker badge — the thing that explains why two fills cost differently. */
  showLiquidity?: boolean;
  showVenue?: boolean;
  /** Footer with filled quantity, notional, fees and the blended price. */
  showTotals?: boolean;
  onSelect?: (fill: Fill) => void;
  loading?: boolean;
  className?: string;
}

/** Quantity-weighted average price. The blended number a desk actually quotes. */
export function averageFillPrice(fills: readonly Fill[]): number {
  let qty = 0;
  let notional = 0;
  for (const fill of fills) {
    if (!Number.isFinite(fill.price) || !Number.isFinite(fill.quantity)) continue;
    qty += Math.abs(fill.quantity);
    notional += Math.abs(fill.quantity) * fill.price;
  }
  return qty === 0 ? 0 : notional / qty;
}

/**
 * Executions, not instructions.
 *
 * The blotter answers "what did I send and is it still working". This answers
 * "what did I actually get, at what blended price, and what did it cost me" —
 * and those are different questions the moment an order fills in pieces.
 *
 * The totals row is weighted by quantity rather than averaged across rows,
 * because an unweighted mean of fill prices is wrong on every partial
 * sequence and wrong in a way that looks plausible.
 */
export function FillsTable({
  fills,
  instrument,
  showFees = true,
  showLiquidity = true,
  showVenue = false,
  showTotals = true,
  onSelect,
  loading = false,
  className,
}: FillsTableProps) {
  const inst = useInstrument(instrument);
  const sizeDigits = inst.sizePrecision ?? 0;
  const rows = toArray(fills);

  const totals = useMemo(() => {
    let quantity = 0;
    let notional = 0;
    let fees = 0;
    for (const fill of rows) {
      const signed = fill.side === 'buy' ? 1 : -1;
      quantity += signed * fill.quantity;
      notional += Math.abs(fill.quantity) * fill.price;
      fees += fill.fee ?? 0;
    }
    return { quantity, notional, fees, average: averageFillPrice(rows) };
  }, [rows]);

  const columns = 4 + (showFees ? 1 : 0) + (showLiquidity ? 1 : 0) + (showVenue ? 1 : 0) + 1;

  if (loading) return <TableSkeleton rows={4} columns={columns} className={className} />;

  if (rows.length === 0) {
    return (
      <EmptyState
        className={className}
        art={<EmptyTapeArt />}
        title="No fills yet"
        description="Every execution lands here with its price, fee and whether you made or took liquidity."
      />
    );
  }

  return (
    <Table className={className}>
      <TableHeader>
        <TableRow>
          <TableHead>Symbol</TableHead>
          <TableHead>Side</TableHead>
          <TableHead>Qty</TableHead>
          <TableHead>Price</TableHead>
          {showFees && <TableHead>Fee</TableHead>}
          {showLiquidity && <TableHead>Liq</TableHead>}
          {showVenue && <TableHead>Venue</TableHead>}
          <TableHead>Time</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((fill) => (
          <TableRow
            key={fill.id}
            onClick={onSelect ? () => onSelect(fill) : undefined}
            className={onSelect ? 'cursor-pointer' : undefined}
          >
            <TableCell>{fill.symbol}</TableCell>
            <TableCell>
              <span className="flex justify-end">
                <Badge variant={fill.side === 'buy' ? 'up' : 'down'}>
                  {fill.side.toUpperCase()}
                </Badge>
              </span>
            </TableCell>
            <TableCell>{formatQuantity(fill.quantity, sizeDigits)}</TableCell>
            <TableCell className="tabular-nums">
              {formatPrice(fill.price, inst.pricePrecision)}
            </TableCell>
            {showFees && (
              <TableCell
                className={cn('tabular-nums', (fill.fee ?? 0) < 0 && 'text-up')}
                // A rebate is income, not a cost — it should not read as a fee.
                title={(fill.fee ?? 0) < 0 ? 'Maker rebate' : undefined}
              >
                {fill.fee === undefined ? '—' : formatMoney(fill.fee, inst.currency)}
              </TableCell>
            )}
            {showLiquidity && (
              <TableCell className="text-muted-foreground uppercase">
                {fill.liquidity ?? '—'}
              </TableCell>
            )}
            {showVenue && (
              <TableCell className="text-muted-foreground">{fill.venue ?? '—'}</TableCell>
            )}
            <TableCell className="text-muted-foreground">{formatTime(fill.time)}</TableCell>
          </TableRow>
        ))}
      </TableBody>
      {showTotals && (
        <TableFooter>
          <TableRow>
            <TableCell>Total</TableCell>
            <TableCell />
            <TableCell className="tabular-nums">
              {formatQuantity(totals.quantity, sizeDigits)}
            </TableCell>
            <TableCell className="tabular-nums" title="Quantity-weighted average">
              {formatPrice(totals.average, inst.pricePrecision)}
            </TableCell>
            {showFees && (
              <TableCell className="tabular-nums">
                {formatMoney(totals.fees, inst.currency)}
              </TableCell>
            )}
            {showLiquidity && <TableCell />}
            {showVenue && <TableCell />}
            <TableCell className="text-muted-foreground tabular-nums">
              {formatMoney(totals.notional, inst.currency)}
            </TableCell>
          </TableRow>
        </TableFooter>
      )}
    </Table>
  );
}

'use client';

import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-md border px-1.5 py-0.5 text-[10px] font-semibold tracking-wide whitespace-nowrap [&>svg]:pointer-events-none [&>svg:not([class*='size-'])]:size-3",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground border-transparent',
        secondary: 'bg-secondary text-secondary-foreground border-transparent',
        outline: 'text-foreground',
        up: 'bg-up-muted text-up border-transparent',
        down: 'bg-down-muted text-down border-transparent',
        flat: 'bg-muted text-flat border-transparent',
      },
    },
    defaultVariants: { variant: 'default' },
  },
);

function Badge({
  className,
  variant,
  asChild = false,
  ...props
}: ComponentProps<'span'> & VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'span';
  return (
    <Comp data-slot="badge" className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

'use client';

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * shadcn/ui Table, retuned for data density: tighter rows, right-aligned
 * numeric columns by default, and a sticky header so the column names survive
 * a long blotter.
 */
function Table({ className, ...props }: ComponentProps<'table'>) {
  return (
    <table
      data-slot="table"
      className={cn('w-full caption-bottom border-collapse text-xs', className)}
      {...props}
    />
  );
}

function TableHeader({ className, ...props }: ComponentProps<'thead'>) {
  return <thead data-slot="table-header" className={cn('[&_tr]:border-b', className)} {...props} />;
}

function TableBody({ className, ...props }: ComponentProps<'tbody'>) {
  return <tbody data-slot="table-body" className={cn('', className)} {...props} />;
}

function TableFooter({ className, ...props }: ComponentProps<'tfoot'>) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn('bg-muted/50 border-t font-medium', className)}
      {...props}
    />
  );
}

function TableRow({ className, ...props }: ComponentProps<'tr'>) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        'hover:bg-muted/50 data-[state=selected]:bg-muted border-b transition-colors',
        className,
      )}
      {...props}
    />
  );
}

function TableHead({ className, ...props }: ComponentProps<'th'>) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        'text-muted-foreground bg-muted sticky top-0 z-10 h-7 px-2.5 text-right text-[10px] font-semibold tracking-wider whitespace-nowrap uppercase first:text-left',
        className,
      )}
      {...props}
    />
  );
}

function TableCell({ className, ...props }: ComponentProps<'td'>) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        'font-mono px-2.5 py-1.5 text-right whitespace-nowrap tabular-nums first:text-left first:font-sans first:font-semibold',
        className,
      )}
      {...props}
    />
